<script lang="ts" setup>
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Alert as AAlert, Button as AButton, Card as ACard, Checkbox as ACheckbox, Col as ACol, Divider as ADivider, Drawer as ADrawer, Empty as AEmpty, Form as AForm, FormItem as AFormItem, Input as AInput, Textarea as ATextarea, InputNumber as AInputNumber, Row as ARow, Select as ASelect, Space as ASpace, Table as ATable, Tabs as ATabs, TabPane as ATabPane, Tag as ATag, message } from 'ant-design-vue';
import MetricGrid from '#/components/operations/MetricGrid.vue';
import KeyValueEditor from '#/components/openresty/KeyValueEditor.vue';
import { type PageResult, useServerPagination } from '#/utils/server-pagination';
type Center={id:string;code:string;name:string}; type NginxNode={id:string;name:string;host:string;servicePort:number;enabled:boolean}; type DictionaryOption={value:string;label:string}; type Upstream={id:string;name:string;keepaliveConnections:number}; type Certificate={id:string;name:string;commonName:string;enabled:boolean}; type ModeOrder='BLACKLIST_FIRST'|'WHITELIST_FIRST'; type HttpServer={id:string;domain:string;listenPort:number;sslEnabled:boolean;certificateId?:string;upstreamId?:string;accessLog?:string;errorLog?:string;ipPolicyEnabled:boolean;apiPolicyEnabled:boolean;ipPolicyModeOrder:ModeOrder;apiPolicyModeOrder:ModeOrder;rootPath?:string;hideVersion:boolean;responseHeaders:string[]}; type LocationAction='PROXY'|'STATIC'|'RETURN'; type HttpLocation={id:string;path:string;methods:string[];contentTypes:string[];headerLengthMin:number;headerLengthMax:number;bodyLengthMin:number;bodyLengthMax:number;upstreamId?:string;proxyConnectTimeoutMs:number;proxyReadTimeoutMs:number;proxySendTimeoutMs:number;rateLimitEnabled:boolean;ratePerSecond:number;rateLimitBurst:number;rateLimitNodelay:boolean;dynamicDnsEnabled:boolean;dynamicDnsHost?:string;dynamicDnsPort?:number;action:LocationAction;rootPath?:string;aliasPath?:string;returnStatus?:number;returnBody?:string;returnContentTypeMode:'REQUEST'|'CUSTOM';returnContentType?:string;responseHeaders:string[]};
const router=useRouter(), route=useRoute(); const centers=ref<Center[]>([]), nodes=ref<NginxNode[]>([]), upstreams=ref<Upstream[]>([]), servers=ref<HttpServer[]>([]), locations=ref<HttpLocation[]>([]), upstreamRows=ref<Upstream[]>([]), serverRows=ref<HttpServer[]>([]), locationRows=ref<HttpLocation[]>([]), certificates=ref<Certificate[]>([]); const selectedCenterId=ref<string>(), selectedNodeId=ref<string>(), selectedServerId=ref<string>(), loading=ref(false); const activeTab=ref('upstream'); const httpSettings=ref({rootPath:'',hideVersion:true,responseHeaders:['X-Frame-Options: SAMEORIGIN','X-Content-Type-Options: nosniff','Referrer-Policy: strict-origin-when-cross-origin']});
const upstreamOpen=ref(false),serverOpen=ref(false),locationOpen=ref(false),certificateOpen=ref(false); const editingUpstreamId=ref<string>(),editingServerId=ref<string>(),editingLocationId=ref<string>(),editingCertificateId=ref<string>();
const freshUpstream=()=>({name:'',keepaliveConnections:32}); const freshServer=()=>({domain:'',listenPort:80,sslEnabled:false,certificateId:undefined as string|undefined,upstreamId:undefined as string|undefined,accessLog:'',errorLog:'',ipPolicyEnabled:false,apiPolicyEnabled:false,ipPolicyModeOrder:'BLACKLIST_FIRST' as ModeOrder,apiPolicyModeOrder:'BLACKLIST_FIRST' as ModeOrder,rootPath:'',hideVersion:true,responseHeaders:['X-Frame-Options: SAMEORIGIN','X-Content-Type-Options: nosniff','Referrer-Policy: strict-origin-when-cross-origin']}); const freshCertificate=()=>({name:'',commonName:'',certificatePem:'',privateKeyPem:'',chainPem:'',enabled:true}); const freshLocation=()=>({path:'/',methods:['GET'] as string[],contentTypes:[] as string[],headerLengthMin:0,headerLengthMax:8192,bodyLengthMin:0,bodyLengthMax:1_048_576,upstreamId:undefined as string|undefined,proxyConnectTimeoutMs:5000,proxyReadTimeoutMs:60_000,proxySendTimeoutMs:60_000,rateLimitEnabled:false,ratePerSecond:10,rateLimitBurst:0,rateLimitNodelay:false,dynamicDnsEnabled:false,dynamicDnsHost:'',dynamicDnsPort:80,action:'PROXY' as LocationAction,rootPath:'',aliasPath:'',returnStatus:200,returnBody:'',returnContentTypeMode:'CUSTOM' as 'REQUEST'|'CUSTOM',returnContentType:'application/json',responseHeaders:['X-Frame-Options: SAMEORIGIN','X-Content-Type-Options: nosniff']});
const upstreamForm=ref(freshUpstream()),serverForm=ref(freshServer()),certificateForm=ref(freshCertificate()),locationForm=ref(freshLocation());
const upstreamPager=useServerPagination(),serverPager=useServerPagination(),locationPager=useServerPagination();
const contentTypeOptions=ref<DictionaryOption[]>([]); const methodOptions=ref<DictionaryOption[]>([]);
const selectedCenter=computed(()=>centers.value.find(v=>v.id===selectedCenterId.value)); const selectedNode=computed(()=>nodes.value.find(v=>v.id===selectedNodeId.value)); const selectedServer=computed(()=>servers.value.find(v=>v.id===selectedServerId.value)); const upstreamOptions=computed(()=>upstreams.value.map(v=>({value:v.id,label:v.name}))); const certificateOptions=computed(()=>certificates.value.filter(v=>v.enabled).map(v=>({value:v.id,label:`${v.name}（${v.commonName}）`}))); const upstreamName=(id?:string)=>upstreams.value.find(v=>v.id===id)?.name||'未绑定'; const hasCenter=computed(()=>Boolean(selectedCenterId.value)); const hasServer=computed(()=>Boolean(selectedServerId.value));
const reportMetrics=computed(()=>[{label:'HTTP Server',value:servers.value.length,suffix:'个',hint:`${new Set(servers.value.map(v=>v.domain)).size} 个域名`,tone:'blue'},{label:'当前 Location',value:locations.value.length,suffix:'个',hint:selectedServer.value?`${selectedServer.value.domain}:${selectedServer.value.listenPort}`:'请选择 Server',tone:'purple'},{label:'HTTP Upstream',value:upstreams.value.length,suffix:'组',hint:'可用转发目标',tone:'green'},{label:'TLS Server',value:servers.value.filter(v=>v.sslEnabled).length,suffix:'个',hint:`${certificates.value.filter(v=>v.enabled).length} 张可用证书`,tone:'cyan'}]);
const serverColumns=[{dataIndex:'domain',key:'domain',title:'域名'},{dataIndex:'listenPort',key:'listenPort',title:'端口'},{dataIndex:'sslEnabled',key:'sslEnabled',title:'TLS'},{dataIndex:'upstreamId',key:'upstreamId',title:'默认 Upstream'},{key:'action',title:'操作',width:200}]; const upstreamColumns=[{dataIndex:'name',key:'name',title:'服务标识'},{dataIndex:'keepaliveConnections',key:'keepaliveConnections',title:'Keepalive 连接数'},{key:'action',title:'操作',width:130}]; const locationColumns=[{dataIndex:'path',key:'path',title:'匹配路径'},{dataIndex:'methods',key:'methods',title:'请求方法'},{dataIndex:'contentTypes',key:'contentTypes',title:'Content-Type'},{dataIndex:'upstreamId',key:'upstreamId',title:'转发 Upstream'},{key:'condition',title:'长度条件'},{key:'action',title:'操作',width:130}];
async function request<T>(path:string,options?:RequestInit):Promise<T>{const r=await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...(options?.headers??{})}});if(!r.ok){const b=await r.json().catch(()=>({}));throw new Error(b.detail||b.message||'请求失败');}return r.status===204?(undefined as T):r.json() as Promise<T>}
async function loadCenters(){loading.value=true;try{centers.value=await request<Center[]>('/centers');const requested=String(route.query.centerId||'');const center=centers.value.find(v=>v.id===requested)||centers.value[0];if(center)await selectCenter(center.id)}catch(e){message.error(e instanceof Error?e.message:'加载中心失败')}finally{loading.value=false}}
async function loadDictionaries(){try{const [contentTypes,methods]=await Promise.all([request<DictionaryOption[]>('/dictionaries/HTTP_CONTENT_TYPE'),request<DictionaryOption[]>('/dictionaries/HTTP_METHOD')]);contentTypeOptions.value=contentTypes.map(item=>({...item,label:`${item.label}（${item.value}）`}));methodOptions.value=methods.map(item=>({...item,label:`${item.label}（${item.value}）`}))}catch(e){message.error(e instanceof Error?e.message:'加载下拉选项失败')}}
async function loadHttpPage(kind:'upstream'|'server'){if(!selectedCenterId.value)return;const pager=kind==='upstream'?upstreamPager:serverPager;const path=kind==='upstream'?'http/upstreams/paged':'http/servers/paged';const result=await request<PageResult<any>>(`/centers/${selectedCenterId.value}/${path}?${pager.query()}`);const items=pager.apply(result);if(kind==='upstream')upstreamRows.value=items;else serverRows.value=items}
async function changeHttpPage(kind:'upstream'|'server',p:any){const pager=kind==='upstream'?upstreamPager:serverPager;pager.change(p);await loadHttpPage(kind)}
async function selectCenter(id:string){selectedCenterId.value=id;selectedNodeId.value=undefined;selectedServerId.value=undefined;locations.value=[];locationRows.value=[];upstreamPager.reset();serverPager.reset();try{const values=await Promise.all([request<NginxNode[]>(`/centers/${id}/nodes`),request<Upstream[]>(`/centers/${id}/http/upstreams`),request<HttpServer[]>(`/centers/${id}/http/servers`),request<Certificate[]>(`/centers/${id}/tls-certificates`),request<any>(`/centers/${id}/http/settings`)]);[nodes.value,upstreams.value,servers.value,certificates.value,httpSettings.value]=values as any;const requestedNode=String(route.query.nodeId||'');selectedNodeId.value=nodes.value.some(v=>v.id===requestedNode)?requestedNode:(nodes.value.find(v=>v.enabled)?.id||nodes.value[0]?.id);await Promise.all([loadHttpPage('upstream'),loadHttpPage('server')])}catch(e){message.error(e instanceof Error?e.message:'加载 HTTP 配置失败')}}
async function manageLocations(record:HttpServer){await selectServer(record.id);openServer(record)}
async function saveHttpSettings(){if(!selectedCenterId.value)return;try{await request(`/centers/${selectedCenterId.value}/http/settings`,{method:'PUT',body:JSON.stringify(httpSettings.value)});message.success('HTTP 全局指令已保存，发布后生效')}catch(e){message.error(e instanceof Error?e.message:'保存 HTTP 全局指令失败')}}
async function loadLocationPage(){if(!selectedCenterId.value||!selectedServerId.value)return;locationRows.value=locationPager.apply(await request<PageResult<HttpLocation>>(`/centers/${selectedCenterId.value}/http/servers/${selectedServerId.value}/locations/paged?${locationPager.query()}`))}
async function changeLocationPage(p:any){locationPager.change(p);await loadLocationPage()}
async function selectServer(id:string){selectedServerId.value=id;locations.value=[];locationPager.reset();if(!selectedCenterId.value)return;try{locations.value=await request<HttpLocation[]>(`/centers/${selectedCenterId.value}/http/servers/${id}/locations`);await loadLocationPage()}catch(e){message.error(e instanceof Error?e.message:'加载 Location 失败')}}
function openUpstream(v?:Upstream){editingUpstreamId.value=v?.id;upstreamForm.value=v?{name:v.name,keepaliveConnections:v.keepaliveConnections}:freshUpstream();upstreamOpen.value=true} function openServer(v?:HttpServer){if(v&&v.id!==selectedServerId.value)void selectServer(v.id);editingServerId.value=v?.id;serverForm.value=v?{domain:v.domain,listenPort:v.listenPort,sslEnabled:v.sslEnabled,upstreamId:v.upstreamId,accessLog:v.accessLog||'',errorLog:v.errorLog||'',ipPolicyEnabled:v.ipPolicyEnabled,apiPolicyEnabled:v.apiPolicyEnabled,ipPolicyModeOrder:v.ipPolicyModeOrder||'BLACKLIST_FIRST',apiPolicyModeOrder:v.apiPolicyModeOrder||'BLACKLIST_FIRST',rootPath:v.rootPath||'',hideVersion:v.hideVersion!==false,responseHeaders:v.responseHeaders||[]}:freshServer();serverOpen.value=true} function openLocation(v?:HttpLocation){editingLocationId.value=v?.id;locationForm.value=v?{...freshLocation(),...v,responseHeaders:v.responseHeaders||[]}:freshLocation();locationOpen.value=true}
function openCertificate(v?:Certificate){editingCertificateId.value=v?.id;certificateForm.value=v?{name:v.name,commonName:v.commonName,certificatePem:'',privateKeyPem:'',chainPem:'',enabled:v.enabled}:freshCertificate();certificateOpen.value=true}
async function saveUpstream(){if(!selectedCenterId.value)return;try{await request(`/centers/${selectedCenterId.value}/http/upstreams${editingUpstreamId.value?`/${editingUpstreamId.value}`:''}`,{method:editingUpstreamId.value?'PUT':'POST',body:JSON.stringify(upstreamForm.value)});upstreamOpen.value=false;await selectCenter(selectedCenterId.value);message.success(editingUpstreamId.value?'Upstream 已更新':'Upstream 已创建')}catch(e){message.error(e instanceof Error?e.message:'保存 Upstream 失败')}}
async function saveServer(){if(!selectedCenterId.value)return;try{const {ipPolicyEnabled,apiPolicyEnabled,ipPolicyModeOrder,apiPolicyModeOrder,rootPath,hideVersion,responseHeaders,...serverPayload}=serverForm.value;const result=await request<HttpServer>(`/centers/${selectedCenterId.value}/http/servers${editingServerId.value?`/${editingServerId.value}`:''}`,{method:editingServerId.value?'PUT':'POST',body:JSON.stringify(serverPayload)});await Promise.all([request(`/centers/${selectedCenterId.value}/http/servers/${result.id}/policy-settings`,{method:'PUT',body:JSON.stringify({ipPolicyEnabled,apiPolicyEnabled,ipPolicyModeOrder,apiPolicyModeOrder})}),request(`/centers/${selectedCenterId.value}/http/servers/${result.id}/directives`,{method:'PUT',body:JSON.stringify({rootPath,hideVersion,responseHeaders})})]);serverOpen.value=false;await selectCenter(selectedCenterId.value);await selectServer(result.id);message.success(editingServerId.value?'HTTP Server 已更新':'HTTP Server 已创建')}catch(e){message.error(e instanceof Error?e.message:'保存 HTTP Server 失败')}}
async function saveCertificate(){if(!selectedCenterId.value)return;try{const payload={...certificateForm.value};if(editingCertificateId.value&&!payload.certificatePem&&!payload.privateKeyPem){delete (payload as any).certificatePem;delete (payload as any).privateKeyPem;}await request(`/centers/${selectedCenterId.value}/tls-certificates${editingCertificateId.value?`/${editingCertificateId.value}`:''}`,{method:editingCertificateId.value?'PUT':'POST',body:JSON.stringify(payload)});certificateOpen.value=false;await selectCenter(selectedCenterId.value);message.success(editingCertificateId.value?'证书已更新':'证书已新增')}catch(e){message.error(e instanceof Error?e.message:'保存证书失败')}}
async function saveLocation(){if(!selectedCenterId.value||!selectedServerId.value||(locationForm.value.action==='PROXY'&&!locationForm.value.upstreamId))return;try{const {action,rootPath,aliasPath,returnStatus,returnBody,returnContentTypeMode,returnContentType,responseHeaders,...locationPayload}=locationForm.value;const result=await request<HttpLocation>(`/centers/${selectedCenterId.value}/http/servers/${selectedServerId.value}/locations${editingLocationId.value?`/${editingLocationId.value}`:''}`,{method:editingLocationId.value?'PUT':'POST',body:JSON.stringify(locationPayload)});await request(`/centers/${selectedCenterId.value}/http/servers/${selectedServerId.value}/locations/${result.id}/directives`,{method:'PUT',body:JSON.stringify({action,rootPath,aliasPath,returnStatus,returnBody,returnContentTypeMode,returnContentType,responseHeaders})});locationOpen.value=false;await selectServer(selectedServerId.value);message.success(editingLocationId.value?'Location 已更新':'Location 已创建')}catch(e){message.error(e instanceof Error?e.message:'保存 Location 失败')}}
async function remove(path:string,title:string){try{await request(path,{method:'DELETE'});if(selectedCenterId.value)await selectCenter(selectedCenterId.value);message.success(`${title}已删除`)}catch(e){message.error(e instanceof Error?e.message:`删除${title}失败`)}}
onMounted(()=>{loadCenters();loadDictionaries()});
</script>
<template>
  <div class="http-config-page ops-page">
    <a-card :bordered="false" title="HTTP 配置管理">
      <a-alert class="mb-4" type="info" show-icon message="按 Upstream、Server、Location 的顺序维护配置。选择 Server 后即可管理其路由。" />
      <a-form layout="inline">
        <a-form-item label="配置中心">
          <a-select v-model:value="selectedCenterId" class="w-80" placeholder="请选择要维护的中心" :options="centers.map(v=>({value:v.id,label:`${v.name}（${v.code}）`}))" @change="selectCenter" />
        </a-form-item>
        <a-form-item label="OpenResty 实例"><a-select v-model:value="selectedNodeId" class="w-96" allow-clear placeholder="选择实例以查看部署上下文" :options="nodes.map(v=>({value:v.id,label:`${v.name}（${v.host}:${v.servicePort}）`}))" /></a-form-item>
      </a-form>
      <a-alert class="mt-4" type="info" show-icon :message="`配置层级：${selectedCenter?.name || '未选择中心'} → ${selectedNode ? `${selectedNode.name}（${selectedNode.host}:${selectedNode.servicePort}）` : '全部实例'} → HTTP`" description="中心级 HTTP 配置会渲染并发布到该中心所有启用的 OpenResty 实例；实例选择用于定位当前管理与发布上下文。" />
    </a-card>

    <metric-grid class="compact-metrics" :metrics="reportMetrics" />
    <a-tabs v-if="hasCenter" v-model:active-key="activeTab" class="http-level-tabs mt-4">
      <a-tab-pane key="upstream" tab="Upstream 配置">
    <div>
        <a-card :bordered="false" :title="selectedCenter ? `${selectedCenter.name} 的 Upstream` : 'HTTP Upstream'">
          <template #extra><a-button type="primary" :disabled="!hasCenter" @click="openUpstream()">新增 Upstream</a-button></template>
          <a-table :columns="upstreamColumns" :data-source="upstreamRows" :loading="loading" :pagination="upstreamPager.table.value" @change="(p:any)=>changeHttpPage('upstream',p)" row-key="id" size="small" :locale="{ emptyText: hasCenter ? '还没有 Upstream，请先新增一个服务后端。' : '请先选择配置中心。' }">
            <template #bodyCell="{ column, record }">
              <template v-if="column.key === 'action'"><a-space :size="0"><a-button type="link" @click="openUpstream(record)">编辑</a-button><a-popconfirm title="确认删除该 Upstream？" @confirm="remove(`/centers/${selectedCenterId}/http/upstreams/${record.id}`, 'Upstream')"><a-button danger type="link">删除</a-button></a-popconfirm></a-space></template>
            </template>
          </a-table>
        </a-card>
    </div>
      </a-tab-pane>
      <a-tab-pane key="server" tab="Server 配置">
      <div>
        <a-card :bordered="false" :title="selectedCenter ? `${selectedCenter.name} 的 Server` : 'HTTP Server'">
          <template #extra><a-button type="primary" :disabled="!hasCenter" @click="openServer()">新增 Server</a-button></template>
          <a-table :columns="serverColumns" :data-source="serverRows" :loading="loading" :pagination="serverPager.table.value" @change="(p:any)=>changeHttpPage('server',p)" row-key="id" size="small" :row-class-name="(record: HttpServer) => record.id === selectedServerId ? 'selected-server-row' : ''" :locale="{ emptyText: hasCenter ? '还没有 Server，请新增域名和监听端口。' : '请先选择配置中心。' }">
            <template #bodyCell="{ column, record }">
              <template v-if="column.key === 'sslEnabled'"><a-tag :color="record.sslEnabled ? 'green' : 'default'">{{ record.sslEnabled ? '已启用' : '未启用' }}</a-tag></template>
              <template v-else-if="column.key === 'upstreamId'">{{ upstreamName(record.upstreamId) }}</template>
              <template v-else-if="column.key === 'action'"><a-space :size="0"><a-button type="link" @click="manageLocations(record)">管理 Location</a-button><a-button type="link" @click="openServer(record)">编辑</a-button><a-popconfirm title="确认删除该 Server 及其全部 Location？" @confirm="remove(`/centers/${selectedCenterId}/http/servers/${record.id}`, 'Server')"><a-button danger type="link">删除</a-button></a-popconfirm></a-space></template>
            </template>
          </a-table>
        </a-card>
      </div>
      </a-tab-pane>
      <a-tab-pane key="security" tab="HTTP 安全配置">
        <a-card :bordered="false" title="HTTP 全局安全与静态内容"><a-alert class="mb-4" type="info" show-icon message="全局 root 与安全响应头会被 Server、Location 的同名配置覆盖；所有 add_header 都使用 always。"/><a-row :gutter="16"><a-col :lg="8" :xs="24"><a-form-item label="root 内容目录"><a-input v-model:value="httpSettings.rootPath" placeholder="/srv/openresty-content"/></a-form-item></a-col><a-col :lg="5" :xs="24"><a-form-item><a-checkbox v-model:checked="httpSettings.hideVersion">隐藏版本</a-checkbox></a-form-item></a-col><a-col :lg="11" :xs="24"><a-form-item label="响应头与安全头"><key-value-editor v-model="httpSettings.responseHeaders" /></a-form-item></a-col></a-row><div class="flex justify-end"><a-button type="primary" @click="saveHttpSettings">保存 HTTP 全局指令</a-button></div></a-card>
      </a-tab-pane>
    </a-tabs>

    <a-card v-if="false" class="mt-5" :bordered="false" :title="selectedServer ? `${selectedServer.domain}:${selectedServer.listenPort} 的 Location` : 'Location 路由'">
      <template #extra><a-button type="primary" :disabled="!hasServer" @click="openLocation()">新增 Location</a-button></template>
      <template v-if="!hasServer"><a-empty description="从上方选择一个 Server 后，可在此维护 Location 路由。" /></template>
      <a-table v-else :columns="locationColumns" :data-source="locationRows" :pagination="locationPager.table.value" @change="changeLocationPage" row-key="id" :locale="{ emptyText: '该 Server 暂无 Location，新增一条路由开始配置。' }">
        <template #bodyCell="{ column, record }">
          <template v-if="column.key === 'methods'"><a-tag v-for="item in record.methods" :key="item">{{ item }}</a-tag></template>
          <template v-else-if="column.key === 'contentTypes'"><span :class="{ 'text-gray-400': !record.contentTypes.length }">{{ record.contentTypes.length ? record.contentTypes.join(', ') : '不限制' }}</span></template>
          <template v-else-if="column.key === 'upstreamId'">{{ upstreamName(record.upstreamId) }}</template>
          <template v-else-if="column.key === 'condition'">请求头 {{ record.headerLengthMin }} ～ {{ record.headerLengthMax }}；请求体 {{ record.bodyLengthMin }} ～ {{ record.bodyLengthMax }}</template>
          <template v-else-if="column.key === 'action'"><a-space :size="0"><a-button type="link" @click="openLocation(record)">编辑</a-button><a-popconfirm title="确认删除该 Location？" @confirm="remove(`/centers/${selectedCenterId}/http/servers/${selectedServerId}/locations/${record.id}`, 'Location')"><a-button danger type="link">删除</a-button></a-popconfirm></a-space></template>
        </template>
      </a-table>
    </a-card>

    <a-drawer v-model:open="upstreamOpen" :title="editingUpstreamId ? '编辑 HTTP Upstream' : '新增 HTTP Upstream'" :width="480" destroy-on-close>
      <a-alert class="mb-4" type="info" show-icon message="Upstream 用于定义可被 Server 和 Location 引用的后端服务。" />
      <a-form layout="vertical"><a-form-item label="服务标识" required><a-input v-model:value="upstreamForm.name" placeholder="例如：order-service" /></a-form-item><a-form-item label="Keepalive 连接数" required extra="空闲连接池的最大连接数。"><a-input-number v-model:value="upstreamForm.keepaliveConnections" class="w-full" :min="1" :max="10000" /></a-form-item></a-form>
      <template #footer><div class="flex justify-end gap-2"><a-button @click="upstreamOpen = false">取消</a-button><a-button type="primary" @click="saveUpstream">保存</a-button></div></template>
    </a-drawer>

    <a-drawer v-model:open="serverOpen" :title="editingServerId ? '编辑 HTTP Server' : '新增 HTTP Server'" :width="520" destroy-on-close>
      <a-alert class="mb-4" type="info" show-icon message="一个 Server 对应一个域名和监听端口；路由在保存后通过“管理 Location”维护。" />
      <a-alert class="mb-4" type="warning" show-icon message="目录只允许填写 OpenResty 容器已挂载的受控目录，例如 /srv/openresty-content/site-a；禁止使用 ..。安全头会自动附加 always。" />
      <a-form layout="vertical" class="mb-4"><a-form-item label="root 内容目录"><a-input v-model:value="serverForm.rootPath" placeholder="/srv/openresty-content/site-a" /></a-form-item><a-form-item><a-checkbox v-model:checked="serverForm.hideVersion">隐藏版本并清除 Server 响应头</a-checkbox></a-form-item><a-form-item label="响应头与安全头" extra="格式 Header-Name: value；自动附加 always。"><key-value-editor v-model="serverForm.responseHeaders" /></a-form-item></a-form>
      <a-form layout="vertical"><a-row :gutter="16"><a-col :span="14"><a-form-item label="域名" required><a-input v-model:value="serverForm.domain" placeholder="例如：api.example.com" /></a-form-item></a-col><a-col :span="10"><a-form-item label="监听端口" required><a-input-number v-model:value="serverForm.listenPort" class="w-full" :min="1" :max="65535" /></a-form-item></a-col></a-row><a-form-item label="默认 Upstream" extra="当 Location 未单独指定时使用；可稍后在 Location 中覆盖。"><a-select v-model:value="serverForm.upstreamId" allow-clear show-search placeholder="请选择后端服务" :options="upstreamOptions" /></a-form-item><a-row :gutter="16"><a-col :span="12"><a-form-item label="访问日志"><a-input v-model:value="serverForm.accessLog" placeholder="留空自动生成" /></a-form-item></a-col><a-col :span="12"><a-form-item label="错误日志"><a-input v-model:value="serverForm.errorLog" placeholder="留空自动生成" /></a-form-item></a-col></a-row><a-form-item><a-checkbox v-model:checked="serverForm.sslEnabled">启用 TLS</a-checkbox></a-form-item><a-divider orientation="left">访问策略</a-divider><a-row :gutter="16"><a-col :span="12"><a-form-item><a-checkbox v-model:checked="serverForm.ipPolicyEnabled">启用 IP 策略</a-checkbox></a-form-item></a-col><a-col :span="12"><a-form-item><a-checkbox v-model:checked="serverForm.apiPolicyEnabled">启用 API 策略</a-checkbox></a-form-item></a-col></a-row><a-row :gutter="16"><a-col :span="12"><a-form-item label="IP 冲突优先级"><a-select v-model:value="serverForm.ipPolicyModeOrder" :options="[{value:'BLACKLIST_FIRST',label:'黑名单优先（BLACKLIST_FIRST）'},{value:'WHITELIST_FIRST',label:'白名单优先（WHITELIST_FIRST）'}]" /></a-form-item></a-col><a-col :span="12"><a-form-item label="API 冲突优先级"><a-select v-model:value="serverForm.apiPolicyModeOrder" :options="[{value:'BLACKLIST_FIRST',label:'黑名单优先（BLACKLIST_FIRST）'},{value:'WHITELIST_FIRST',label:'白名单优先（WHITELIST_FIRST）'}]" /></a-form-item></a-col></a-row></a-form>
      <a-divider v-if="editingServerId" orientation="left">Location 路由</a-divider>
      <template v-if="editingServerId"><div class="mb-3 flex items-center justify-between"><span class="text-sm text-gray-500">在当前抽屉中维护 {{ serverForm.domain }}:{{ serverForm.listenPort }} 的路由。</span><a-button size="small" type="primary" @click="openLocation()">新增 Location</a-button></div><a-table size="small" :columns="locationColumns" :data-source="locationRows" :pagination="locationPager.table.value" row-key="id" @change="changeLocationPage"><template #emptyText><a-empty description="当前 Server 暂无 Location" /></template><template #bodyCell="{ column, record }"><template v-if="column.key === 'methods'"><a-tag v-for="item in record.methods" :key="item">{{ item }}</a-tag></template><template v-else-if="column.key === 'contentTypes'">{{ record.contentTypes.length ? record.contentTypes.join(', ') : '不限制' }}</template><template v-else-if="column.key === 'upstreamId'">{{ upstreamName(record.upstreamId) }}</template><template v-else-if="column.key === 'condition'">请求头 {{ record.headerLengthMin }} ～ {{ record.headerLengthMax }}；请求体 {{ record.bodyLengthMin }} ～ {{ record.bodyLengthMax }}</template><template v-else-if="column.key === 'action'"><a-space :size="0"><a-button type="link" @click="openLocation(record)">编辑</a-button><a-popconfirm title="确认删除该 Location？" @confirm="remove(`/centers/${selectedCenterId}/http/servers/${selectedServerId}/locations/${record.id}`, 'Location')"><a-button danger type="link">删除</a-button></a-popconfirm></a-space></template></template></a-table></template>
      <template #footer><div class="flex justify-end gap-2"><a-button @click="serverOpen = false">取消</a-button><a-button type="primary" @click="saveServer">保存</a-button></div></template>
    </a-drawer>

    <a-drawer v-model:open="locationOpen" :title="editingLocationId ? '编辑 HTTP Location' : '新增 HTTP Location'" :width="720" destroy-on-close>
      <a-alert class="mb-4" type="info" show-icon message="Location 的匹配条件会同时参与运行时访问策略判断；Content-Type 留空时不限制类型。" />
      <a-alert class="mb-4" type="warning" show-icon message="静态文件请选择 root 或 alias 之一；直接返回支持自定义或跟随请求 Content-Type。" />
      <a-form layout="vertical" class="mb-4"><a-row :gutter="16"><a-col :span="12"><a-form-item label="处理方式"><a-select v-model:value="locationForm.action" :options="[{value:'PROXY',label:'代理转发（PROXY）'},{value:'STATIC',label:'静态文件（STATIC）'},{value:'RETURN',label:'直接返回（RETURN）'}]" /></a-form-item></a-col><a-col :span="12"><a-form-item v-if="locationForm.action==='STATIC'" label="root 目录"><a-input v-model:value="locationForm.rootPath" placeholder="/srv/openresty-content/site-a" /></a-form-item><a-form-item v-else-if="locationForm.action==='RETURN'" label="状态码"><a-input-number v-model:value="locationForm.returnStatus" :min="100" :max="599" class="w-full" /></a-form-item></a-col></a-row><a-form-item v-if="locationForm.action==='STATIC'" label="alias 目录" extra="root 与 alias 二选一。"><a-input v-model:value="locationForm.aliasPath" /></a-form-item><a-form-item v-if="locationForm.action==='RETURN'" label="返回内容"><a-textarea v-model:value="locationForm.returnBody" :rows="2" /></a-form-item><a-form-item v-if="locationForm.action==='RETURN'" label="响应 Content-Type"><a-select v-model:value="locationForm.returnContentTypeMode" :options="[{value:'CUSTOM',label:'自定义（CUSTOM）'},{value:'REQUEST',label:'跟随请求（REQUEST）'}]" /></a-form-item><a-form-item label="响应头与安全头"><key-value-editor v-model="locationForm.responseHeaders" /></a-form-item></a-form>
      <a-form layout="vertical"><a-row :gutter="16"><a-col :span="12"><a-form-item label="匹配路径" required><a-input v-model:value="locationForm.path" placeholder="例如：/orders" /></a-form-item></a-col><a-col :span="12"><a-form-item label="转发 Upstream" required><a-select v-model:value="locationForm.upstreamId" show-search placeholder="请选择后端服务" :options="upstreamOptions" /></a-form-item></a-col></a-row><a-form-item label="允许的请求方法" required extra="可选择多个请求方法。"><a-select v-model:value="locationForm.methods" mode="multiple" :options="methodOptions" option-filter-prop="label" placeholder="请选择请求方法" /></a-form-item><a-form-item label="允许的 Content-Type" extra="推荐项由系统字典提供；也可直接输入自定义类型后按回车添加。"><a-select v-model:value="locationForm.contentTypes" mode="tags" :options="contentTypeOptions" option-filter-prop="label" :token-separators="[',']" placeholder="不填写表示不限制" /></a-form-item><a-divider orientation="left">动态域名解析</a-divider><a-form-item><a-checkbox v-model:checked="locationForm.dynamicDnsEnabled">把目标域名赋值给变量，Resolver 缓存过期后重新解析</a-checkbox></a-form-item><a-row v-if="locationForm.dynamicDnsEnabled" :gutter="16"><a-col :span="16"><a-form-item label="目标域名" required><a-input v-model:value="locationForm.dynamicDnsHost" placeholder="api.internal.example.com" /></a-form-item></a-col><a-col :span="8"><a-form-item label="目标端口" required><a-input-number v-model:value="locationForm.dynamicDnsPort" class="w-full" :min="1" :max="65535" /></a-form-item></a-col></a-row><a-divider orientation="left">请求限速</a-divider><a-form-item><a-checkbox v-model:checked="locationForm.rateLimitEnabled">启用按客户端 IP 限速</a-checkbox></a-form-item><a-row v-if="locationForm.rateLimitEnabled" :gutter="16"><a-col :span="8"><a-form-item label="每秒请求数"><a-input-number v-model:value="locationForm.ratePerSecond" class="w-full" :min="1" /></a-form-item></a-col><a-col :span="8"><a-form-item label="突发请求数"><a-input-number v-model:value="locationForm.rateLimitBurst" class="w-full" :min="0" /></a-form-item></a-col><a-col :span="8"><a-form-item><a-checkbox v-model:checked="locationForm.rateLimitNodelay">突发请求不延迟</a-checkbox></a-form-item></a-col></a-row><a-divider orientation="left">请求大小条件（字节）</a-divider><a-row :gutter="16"><a-col :span="6"><a-form-item label="请求头最小"><a-input-number v-model:value="locationForm.headerLengthMin" class="w-full" :min="0" /></a-form-item></a-col><a-col :span="6"><a-form-item label="请求头最大"><a-input-number v-model:value="locationForm.headerLengthMax" class="w-full" :min="0" /></a-form-item></a-col><a-col :span="6"><a-form-item label="请求体最小"><a-input-number v-model:value="locationForm.bodyLengthMin" class="w-full" :min="0" /></a-form-item></a-col><a-col :span="6"><a-form-item label="请求体最大"><a-input-number v-model:value="locationForm.bodyLengthMax" class="w-full" :min="0" /></a-form-item></a-col></a-row><a-divider orientation="left">代理超时（毫秒）</a-divider><a-row :gutter="16"><a-col :span="8"><a-form-item label="连接"><a-input-number v-model:value="locationForm.proxyConnectTimeoutMs" class="w-full" :min="1" /></a-form-item></a-col><a-col :span="8"><a-form-item label="读取"><a-input-number v-model:value="locationForm.proxyReadTimeoutMs" class="w-full" :min="1" /></a-form-item></a-col><a-col :span="8"><a-form-item label="发送"><a-input-number v-model:value="locationForm.proxySendTimeoutMs" class="w-full" :min="1" /></a-form-item></a-col></a-row></a-form>
      <template #footer><div class="flex justify-end gap-2"><a-button @click="locationOpen = false">取消</a-button><a-button type="primary" @click="saveLocation">保存</a-button></div></template>
    </a-drawer>
  </div>
</template>
<style scoped>
.selection-hint { color: var(--ant-color-text-description); font-size: 13px; line-height: 32px; }
:deep(.selected-server-row > td) { background: var(--ant-color-primary-bg); }
:deep(.compact-metrics .ops-metric-grid) { gap: 8px; margin: 12px 0 0; }
:deep(.compact-metrics .ops-metric) { min-height: 66px; padding: 10px 14px; }
:deep(.compact-metrics .ops-metric__value) { font-size: 22px; line-height: 26px; }
:deep(.compact-metrics .ops-metric__hint) { display: none; }
:deep(.http-level-tabs .ant-tabs-nav) { margin-bottom: 12px; padding: 0 12px; border-radius: 6px; background: var(--ant-color-bg-container); }
:deep(.ant-table-wrapper) { width: 100%; }
</style>
